const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=id=>users.find(u=>u.id===id)?.name||data().customers?.find(c=>c.id===id)?.name||id;
const person=id=>{
 const label=String(name(id)||'—'),words=label.trim().split(/\s+/);
 const initials=users.find(u=>u.id===id)?.initials||(words.length>1?words[0][0]+words.at(-1)[0]:label.slice(0,2)).toUpperCase();
 return `<span class="person-name"><span class="person-initials" aria-hidden="true">${esc(initials)}</span><span>${esc(label)}</span></span>`;
};
const $=s=>document.querySelector(s);
const opts=(list,value)=>list.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('');
const input=(label,key,value='',type='text',extra='')=>`<label class="field">${label}<input name="${key}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const quotePrice=q=>q.priceMin!=null&&q.priceMin!==q.amount?`${money(q.priceMin)} – ${money(q.amount)}`:money(q.amount);
const area=(label,key,value='')=>`<label class="field">${label}<textarea name="${key}" rows="3" required maxlength="3000">${esc(value)}</textarea></label>`;
const upload=(label,id,multiple=true)=>`<label class="field">${label}<input type="file" id="${id}" ${multiple?'multiple':''} accept=".pdf,.png,.jpg,.jpeg,.webp,.txt"></label>`;
const date=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Australia/Melbourne',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let mobileDetail=false,customerLogins=[],ledgerScroll=0;
let datePeriod='all',dateFrom='',dateTo='';
function resetRequestDates(){datePeriod='all';dateFrom='';dateTo='';}
let requestTab='todo',requestProject='',requestKind='',projectTab='overview';
let api,scope='requests',selected=null,projectFilter='',statusFilter='All',view='overview',search='',projectSearch='',projectKind='reimbursement';
export function configureBusiness(config){api=config;}
const state=()=>api.getState();
const data=()=>ensureBusiness(state());
const selectedRequest=()=>data().requests.find(r=>r.id===selected);
const stageTitle=r=>({'Corporation review':'Company review','Budget review':'Pre-approval','Supplier review':'Supplier approval'}[r.stage]||r.stage);
const stageBadge=r=>`<span class="oa-stage" data-approval-status="${esc(r.stage)}">${esc(stageTitle(r))}</span>`;
const stageTone=r=>({
 'Supervisor review':'review','Corporation review':'review','PM review':'review',
 'Budget review':'director','Director review':'director','Final acceptance':'director','Project Director sign-off':'director',
 'Finance review':'finance','Supplier review':'finance','Payment review':'finance',
 'Customer confirmation':'director','Customer changes':'returned','Sourcing':'action','Payment setup':'action','Payment documents':'action',
 'Ready to pay':'ready','Completed':'complete','Returned':'returned',
 'Draft':'neutral','Withdrawn':'neutral','Cancelled':'neutral'
}[r.stage]||'neutral');
const statusBadge=r=>`<span class="badge request-status status-${stageTone(r)}">${esc(stageTitle(r))}</span>`;
function requestOwnership(r){const next=[...new Set(assignees(r))],nextLabel=next.some(id=>allowedActions(r,id).includes('approve'))?'Awaiting review':'Next action';return `<dl class="request-ownership"><div class="request-creator"><dt>Created by</dt><dd>${person(r.requester)}</dd></div><div class="request-next ${next.length?'has-assignee':''}"><dt>${nextLabel}</dt><dd class="person-list">${next.length?next.map(id=>person(id)).join(''):'No pending action'}</dd></div></dl>`;}
const labels={invoice:'Upload supplier invoice',...serviceActionLabels,acknowledge:'Acknowledge expense',lodge:'Publish completion',edit:'Edit request',submit:'Submit',approve:'Approve',return:'Return for changes',source:'Select supplier',contract:'Prepare service contract',plan:'Set payment plan',documents:'Upload payment documents',paid:'Record payment',escalate:'Director review',withdraw:'Withdraw',cancel:'Cancel request'};
const documents=files=>files?.length?files.map(f=>`<a class="business-file" href="${esc(f.data)}" download="${esc(f.name)}">↧ ${esc(f.name)}</a>`).join(''):'<span class="muted">No documents</span>';
const archivedFiles=r=>(r.archives||[]).flatMap(a=>[...(a.attachments||[]),...(a.quotes||[]).flatMap(q=>[...q.quoteFiles,...q.contractFiles])]);
function requestDocs(r){return requestDocumentRows(r).map(row=>row.file);}
function attentionText(r){
 if(isServiceV2(r))return nextTask(r,state().actor);
 if(pendingDirectorNotice(r)&&r.directorNotice.recipient===state().actor)return 'Acknowledge expense · no approval required.';
 if(['Ready to pay','Payment review'].includes(r.stage)&&isFinalPayment(r)&&!currentPayment(r).acceptance?.approvedBy)return 'Upload final acceptance evidence for Director approval.';
 if(r.kind==='service'&&r.stage==='Completed'&&r.customerReview&&!r.customerCompletion)return 'Publish completed work to the customer.';
 if(r.stage==='Draft')return 'Finish and submit your draft.';
 if(r.stage==='Withdrawn')return 'Review and resubmit your request.';
 if(r.stage==='Customer changes')return 'Review customer feedback and update your request.';
 if(r.stage==='Sourcing')return 'Pre-approval complete. Describe supplier proposals and select a supplier.';
 if(r.stage==='Contract preparation')return 'Requester: upload the service contract and submit to Finance.';
 if(r.stage==='Contract review')return 'Finance: review the contract, ABN and payment terms.';
 if(r.stage==='Payment documents')return isFinalPayment(r)?'Upload the final invoice and acceptance evidence.':'Upload documents for your next payment.';
 if(r.stage==='Returned')return [...r.history].reverse().find(e=>e.action==='Returned for changes')?.detail||'Update your request.';
 if(r.stage==='Final acceptance')return 'Confirm completion and acceptance before the final payment.';
 return stageTitle(r);
}
function openSavedRequest(id){const r=data().requests.find(r=>r.id===id);if(!r)return;selected=id;mobileDetail=true;view='overview';statusFilter='All';search='';resetRequestDates();scope='requests';requestTab='all';projectFilter='';requestProject='';requestKind='';api.navigate('requests');api.refresh();}
let homeTab='action';
function homePage(){
 const groups=homeGroups(state(),state().actor),upcoming=upcomingPayments(data().requests,state().actor,data().projects,date()),rows=groups[homeTab];
 const titles={action:'Needs your action',waiting:'Waiting for others',returned:'Returned',completed:'Completed'};
 const row=r=>`<tr><td data-label="Request"><button class="oa-request-link" data-open-business="${esc(r.id)}">${esc(r.title)}</button><span class="table-secondary">${esc(r.kind==='corporation'?'Company':data().projects.find(p=>p.id===r.projectId)?.name||'Project')}</span></td><td data-label="Next action">${esc(nextTask(r,state().actor))}<span class="home-assignees">${(pendingDirectorNotice(r)&&r.directorNotice.recipient===state().actor?[state().actor]:assignees(r)).map(person).join('')}</span></td><td data-label="Status">${stageBadge(r)}</td><td data-label="Amount · AUD" class="num"><strong>${money(businessAmount(r))}</strong></td><td class="row-action"><button class="text-btn" data-open-business="${esc(r.id)}">${homeTab==='action'||homeTab==='returned'?'Review':'View'} →</button></td></tr>`;
 return `<div id="business-page" class="business-page request-home"><header class="request-home-heading"><h1>Home</h1><button class="primary request-launch" data-biz="new">+ Request</button></header><nav class="home-task-tabs" aria-label="Your work">${Object.entries(titles).map(([key,title])=>`<button data-home-tab="${key}" aria-pressed="${homeTab===key}">${title}<strong>${groups[key].length}</strong></button>`).join('')}</nav><section class="home-section"><h2>${titles[homeTab]}</h2>${rows.length?`<div class="xero-table-wrap"><table class="xero-table home-task-table"><thead><tr><th>Request</th><th>Next action</th><th>Status</th><th class="num">Amount · AUD</th><th><span class="oa-sr-only">Action</span></th></tr></thead><tbody>${rows.map(row).join('')}</tbody></table></div>`:'<div class="oa-panel-empty"><h3>Nothing here right now</h3><p>New items will appear as requests progress.</p></div>'}</section>${upcoming.length?`<section class="home-section"><h2>Payment reminders <span>Next 7 days & overdue</span></h2>${upcoming.map(({request:r,payment:p})=>`<button class="home-request" data-open-business="${esc(r.id)}"><span><strong>${esc(p.label)} · ${esc(r.title)}</strong><small class="${paymentDueDate(p)<date()?'workspace-overdue':''}">${paymentDueDate(p)<date()?'Overdue':'Due'} ${displayDate(paymentDueDate(p))} · ${esc(paymentReadiness(r,p).status)}</small></span><span class="home-request-amount">${money(p.amount)}</span></button>`).join('')}</section>`:''}</div>`;
}
export function showProjects(){projectTab='overview';mobileDetail=false;projectFilter='';selected=null;search='';projectSearch='';view='overview';}
function customersPage(){
 const customers=data().customers||[];
 return `<div id="business-page" class="business-page customers-register"><header class="business-heading"><h1>Customers <span class="project-count">${customers.length}</span></h1><button class="primary" data-biz="customer-new">+ New customer</button></header><div id="customer-mail-state" class="muted">Checking email delivery…</div>${customers.length?`<div class="xero-table-wrap"><table class="xero-table customers-table"><thead><tr><th>Customer</th><th>Contact</th><th>Status</th><th class="num">Projects</th><th>Actions</th></tr></thead><tbody>${customers.map(c=>`<tr><td data-label="Customer"><button class="oa-request-link" data-edit-customer="${esc(c.id)}">${esc(c.name)}</button></td><td data-label="Contact">${esc(c.contact||'—')}<span class="table-secondary">${esc(c.email)}</span></td><td data-label="Status"><span class="register-status ${c.active?'is-active':''}">${c.active?'Active':'Inactive'}</span></td><td data-label="Projects" class="num">${data().projects.filter(p=>p.customerId===c.id).length}</td><td data-label="Actions"><div class="customer-account-actions"><button data-edit-customer="${esc(c.id)}">Edit</button>${c.active?`<button data-preview-customer="${esc(c.id)}">View portal</button><details class="business-more"><summary>More</summary><div><button data-password-customer="${esc(c.id)}">Set password</button><button data-invite-customer="${esc(c.id)}">Email invitation</button></div></details>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>No customers yet</h3><p>Create a customer, set a password, then assign their projects.</p></div>'}<section class="register-section"><h2>Email activity</h2><div id="customer-mail-list"></div></section></div>`;
}
function customerDialog(c){formDialog(c?'Customer account':'New customer',`${input('Customer / company','name',c?.name,'text','required maxlength="160"')}${input('Contact name','contact',c?.contact,'text','maxlength="160"')}${input('Sign-in email','email',c?.email,'email',`required maxlength="100" ${c?'readonly':''}`)}<p class="muted">After saving, use Set password to create a customer login. Assign their projects in Project settings. Email invitations are optional.</p>${c?`<label><input name="active" type="checkbox" ${c.active?'checked':''}> Active customer account</label>`:''}`,'Save customer',fields=>command('customer',{data:{...fields,id:c?.id,active:c?fields.active==='on':true}}));}
function customerPasswordDialog(c){formDialog('Customer login',`<p>Set a username and password for ${esc(c.name)}. Resetting the password signs out existing sessions.</p>${input('Username','username',customerLogins.find(a=>a.id===c.id)?.username||c.email,'text','required minlength="3" maxlength="100" autocomplete="off" autocapitalize="none"')}${input('New password','password','','password','required minlength="6" maxlength="200" autocomplete="new-password"')}${input('Confirm password','confirm','','password','required minlength="6" maxlength="200" autocomplete="new-password"')}`,'Save login',async fields=>{if(fields.password!==fields.confirm)throw new Error('Passwords do not match.');await requestApi('/api/customer/password',{method:'POST',data:{id:c.id,username:fields.username,password:fields.password}});api.notify('Customer login saved. Share the credentials with the customer.');});}
async function projectInviteDialog(project,customer){
 let settings;try{settings=await requestApi('/api/customer/admin');customerLogins=settings.logins||[];}catch(e){api.notify(e.message);return;}
 const options=data().projects.filter(p=>p.active&&(!customer||p.customerId===customer.id));
 if(!project&&!options.length){api.notify('Assign this customer to an active project first.');return;}
 const c=customer||data().customers?.find(c=>c.id===project?.customerId),invitationId=crypto.randomUUID();
 formDialog('Invite project customer',`${project?`<p class="form-project-name">${esc(project.name)}</p>`:`<label class="field">Project<select name="projectId">${opts(options.map(p=>[p.id,p.name]))}</select></label>`}<div class="form-grid">${input('Customer / company','name',c?.name,'text','required maxlength="160"')}${input('Contact name','contact',c?.contact,'text','maxlength="160"')}</div><div class="form-grid">${input('Customer email','email',c?.email,'email',`required maxlength="100" ${project?.customerAccessEstablished?'readonly':''}`)}${input('Username','username',customerLogins.find(a=>a.id===c?.id)?.username||c?.email,'text','required minlength="3" maxlength="100" autocomplete="off" autocapitalize="none"')}</div><div class="form-grid">${input('Password to send','password','','password','required minlength="6" maxlength="200" autocomplete="new-password"')}${input('Confirm password','confirm','','password','required minlength="6" maxlength="200" autocomplete="new-password"')}</div><p class="muted">For an existing customer, this replaces the login password for all their projects. Existing sessions will be signed out.</p><section class="invitation-preview"><strong>Invitation email</strong><p>From: BOW OA &lt;notifications@wiseway.ai&gt;</p><p>Includes the project name, Customer version link, username and the password entered above.</p><p>${settings.configured?'The invitation will be queued for delivery.':'Resend is not configured. The account will be ready and the invitation will wait for email setup.'}</p></section>`,'Create login & invite',async fields=>{
  if(fields.password!==fields.confirm)throw new Error('Passwords do not match.');
  let result;try{result=await requestApi('/api/customer/project-invite',{method:'POST',data:{...fields,projectId:project?.id||fields.projectId,revision:api.getRevision(),invitationId}});}finally{await api.sync();}
  api.notify(result.status==='accepted'?'Invitation accepted by email provider.':result.configured?'Invitation queued for delivery.':'Customer login ready. Invitation is waiting for Resend setup.');
 });
}
function shareContractsDialog(r){
 const q=r.quotes.find(q=>q.id===r.selectedQuote),shared=r.customerContracts?.files||[];
 formDialog('Share contracts with customer',`<p>Only the selected contract files will be visible in the customer portal. Supplier quotes, ABN checks and payment records stay internal.</p><fieldset class="share-contract-options"><legend>${esc(q.supplier)}</legend>${q.contractFiles.map((f,i)=>`<label><input type="checkbox" name="contract-${i}" ${shared.some(s=>s.data===f.data)?'checked':''}> ${esc(f.name)}</label>`).join('')}</fieldset><label class="field">Note to customer<textarea name="note" rows="3" maxlength="3000">${esc(r.customerContracts?.note||'')}</textarea></label><p class="muted">Uncheck all files to remove shared contract access.</p>`,'Update customer access',fields=>command('share-contracts',{id:r.id,quoteId:q.id,indexes:q.contractFiles.map((f,i)=>i).filter(i=>fields['contract-'+i]==='on'),note:fields.note}));
}
async function projectInvitationState(){
 const box=$('#project-invitation-status');if(!box||role(state().actor)!=='Admin')return;
 try{const result=await requestApi('/api/customer/admin');if(!box.isConnected)return;customerLogins=result.logins||[];const mail=result.mail.find(m=>m.kind==='credentials'&&m.projectId===projectFilter);box.textContent=mail?({queued:result.configured?'Invitation queued':'Invitation waiting for Resend setup',sending:'Sending invitation',accepted:'Invitation accepted by email provider',failed:'Invitation failed — check Customers → Email activity',cancelled:'Invitation cancelled — send a new invitation'})[mail.status]||mail.status:'No account invitation sent yet.';}catch{if(box.isConnected)box.textContent='Invitation status unavailable.';}
}
async function customerMailState(){
 const box=$('#customer-mail-state');if(!box)return;
 try{const result=await requestApi('/api/customer/admin');if(!box.isConnected)return;customerLogins=result.logins||[];box.className=result.configured?'muted':'customer-mail-warning';box.textContent=result.configured?'Email delivery is configured. Sent to provider does not confirm inbox delivery.':'Email delivery is not configured. Invitations and confirmation notices remain queued until a sender is configured.';
 $('#customer-mail-list').innerHTML=result.mail.map(m=>`<div class="customer-mail-row"><div><strong>${esc(m.subject)}</strong><small>${esc(m.to)} · ${new Date(m.createdAt).toLocaleString('en-AU',{timeZone:'Australia/Melbourne'})}</small>${m.error?`<p>${esc(m.error)}</p>`:''}</div><div><span class="badge">${esc(({accepted:'Sent to provider',queued:result.configured?'Queued':'Waiting for email setup',sending:'Sending',failed:'Failed',cancelled:'Cancelled'})[m.status]||m.status)}</span>${m.status==='failed'?` <button data-retry-mail="${esc(m.id)}">Retry</button>`:''}</div></div>`).join('')||'<p class="muted">No email activity yet.</p>';
 document.querySelectorAll('[data-retry-mail]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await requestApi('/api/customer/retry',{method:'POST',data:{id:b.dataset.retryMail}});await customerMailState();}catch(e){api.notify(e.message);b.disabled=false;}});
 }catch(e){box.textContent=e.message;}
}
function projectsHome(){
 const projects=data().projects.filter(p=>`${p.name} ${name(p.pm)} ${name(p.director)} ${(data().customers||[]).find(c=>c.id===p.customerId)?.name||''}`.toLowerCase().includes(projectSearch.toLowerCase()));
 const row=p=>{const requests=data().requests.filter(r=>r.projectId===p.id),active=requests.filter(r=>!['Draft','Withdrawn','Completed','Cancelled'].includes(r.stage)).length;return `<tr><td data-label="Project"><button class="oa-request-link" data-open-project="${esc(p.id)}">${esc(p.name)}</button></td><td data-label="Customer">${esc(data().customers.find(c=>c.id===p.customerId)?.name||'Internal')}</td><td data-label="Project manager">${person(p.pm)}</td><td data-label="Director">${person(p.director)}</td><td data-label="Status"><span class="register-status ${p.active?'is-active':''}">${p.active?'Active':'Inactive'}</span></td><td data-label="Requests" class="num">${requests.length}<span class="table-secondary">${active} in progress</span></td><td class="row-action"><button class="text-btn" data-open-project="${esc(p.id)}" aria-label="Open project ${esc(p.name)}">View →</button></td></tr>`;};
 return `<div id="business-page" class="business-page projects-register"><header class="business-heading"><h1>Projects <span class="project-count">${data().projects.length}</span></h1><div class="project-header-actions">${isManager(state().actor)?'<button data-biz="project-new">+ New project</button>':''}<button class="primary" data-biz="new-context">+ Request</button></div></header><div class="register-toolbar"><label class="register-search"><span>Search</span><input id="project-search" aria-label="Search projects" placeholder="Search projects, customers or people" value="${esc(projectSearch)}"></label><span class="register-count">${projects.length} projects</span></div>${projects.length?`<div class="xero-table-wrap"><table class="xero-table projects-table"><thead><tr><th>Project</th><th>Customer</th><th>Project manager</th><th>Director</th><th>Status</th><th class="num">Requests</th><th><span class="oa-sr-only">Action</span></th></tr></thead><tbody>${projects.map(row).join('')}</tbody></table></div>`:'<div class="empty"><h3>No matching projects</h3><p>Create a project or change your search.</p></div>'}</div>`;
}
function ledgerSummary(requests){
 return `<section class="oa-totals request-totals" aria-label="Filtered request totals"><div><span>Requests</span><strong>${requests.length}</strong></div><div><span>Awaiting your action</span><strong>${requests.filter(r=>needsAction(r,state().actor)).length}</strong></div></section>`;
}
const displayDate=value=>value?new Date(value).toLocaleDateString('en-AU',{timeZone:'Australia/Melbourne',day:'2-digit',month:'short',year:'numeric'}):'—';
function ledger(requests){
 return requests.length?`<div class="oa-table-wrap"><table class="oa-ledger"><thead><tr><th scope="col">Request</th><th scope="col">Created</th><th scope="col">Created by</th><th scope="col">Status / next</th><th scope="col" class="oa-money">Amount · AUD</th><th scope="col"><span class="oa-sr-only">Open request</span></th></tr></thead><tbody>${requests.map(r=>`<tr><td data-label="Request"><button class="oa-request-link" data-business-request="${esc(r.id)}">${esc(r.title)}</button><span class="oa-request-context">${esc(r.kind==='corporation'?'Company':data().projects.find(p=>p.id===r.projectId)?.name||'Project')} · ${esc(kinds[r.kind])}</span><span class="oa-mobile-date">${displayDate(r.createdAt)}</span></td><td data-label="Created">${displayDate(r.createdAt)}</td><td data-label="Created by">${person(r.requester)}</td><td data-label="Status / next">${stageBadge(r)}${requestTab==='todo'&&scope==='requests'?`<span class="oa-task-hint">${esc(attentionText(r))}</span>`:''}<div class="oa-next">${[...new Set(assignees(r))].map(person).join('')||'—'}</div></td><td data-label="Amount · AUD" class="oa-money"><strong>${money(businessAmount(r))}</strong></td><td class="oa-open"><button data-business-request="${esc(r.id)}" aria-label="Open ${esc(r.title)}">↗</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>No matching requests</h3><p>Create a request or change the filters.</p><button data-biz="new-context">+ Request</button></div>`;
}
const projectTabs=[['overview','Overview'],['requests','Requests'],['documents','Contracts & Documents'],['payments','Payments'],['customer','Customer Access']];
function workspaceTabs(items,active,attribute,label){return `<div class="workspace-tabs" role="group" aria-label="${label}">${items.map(([id,title,count])=>`<button ${attribute}="${id}" aria-pressed="${id===active}">${title}${count===undefined?'':`<span>${count}</span>`}</button>`).join('')}</div>`;}
function requestFilters(project){
 const stages=[...new Set(data().requests.map(r=>r.stage))].sort(),kind=project?projectKind:requestKind;
 const chips=[...(!project&&requestProject?[['project',requestProject==='company'?'Company':data().projects.find(p=>p.id===requestProject)?.name||'Project']]:[]),...(kind?[['kind',kinds[kind]]]:[]),...(statusFilter!=='All'?[['status',statusFilter==='Active'?'In progress':stageTitle({stage:statusFilter})]]:[]),...(datePeriod!=='all'?[['date',datePeriod==='custom'?`${dateFrom||'Any date'} – ${dateTo||'Any date'}`:datePeriod==='month'?'This month':'Last month']]:[]),...(search?[['search',`Search: ${search}`]]:[])];
 return `<div class="request-filter-bar"><div class="request-filter-controls"><label class="request-search-field"><span class="filter-search-label">Search</span><input id="business-search" aria-label="Search requests" placeholder="Search requests…" value="${esc(search)}"></label>${!project?`<label class="request-filter-field"><span>Project / company</span><select id="workspace-project" aria-label="Project or company">${opts([['','All'],['company','Company'],...data().projects.map(p=>[p.id,p.name])],requestProject)}</select></label>`:''}<label class="request-filter-field"><span>Status</span><select id="business-status" aria-label="Request status">${opts([['All','All statuses'],['Active','In progress'],...stages.map(stage=>[stage,stageTitle({stage})])],statusFilter)}</select></label><label class="request-filter-field"><span>Created date</span><select id="business-period" aria-label="Created date">${opts([['all','All time'],['month','This month'],['previous','Last month'],['custom','Custom dates']],datePeriod)}</select></label><button class="request-filter-toggle" data-biz="filters" aria-label="More filters">☷ Filters${kind||datePeriod!=='all'?`<span>${Number(!!kind)+Number(datePeriod!=='all')}</span>`:''}</button></div>${chips.length?`<div class="request-filter-chips" aria-label="Active filters">${chips.map(([key,label])=>`<button data-clear-filter="${key}" aria-label="Remove filter: ${esc(label)}">${esc(label)}<span aria-hidden="true">×</span></button>`).join('')}<button class="clear-all-filters" data-clear-filter="all">Clear all</button></div>`:''}</div>`;
}
function moreFilters(initialPeriod=datePeriod){
 const isProject=scope==='projects',kind=isProject?projectKind:requestKind;
 api.modal('Filters',`<form id="request-filters-form"><label class="field">Request type<select name="kind">${opts([['','All types'],...Object.entries(kinds).filter(([id])=>!isProject||id!=='corporation')],kind)}</select></label><label class="field">Created date<select name="period">${opts([['all','All time'],['month','This month'],['previous','Last month'],['custom','Custom dates']],initialPeriod)}</select></label><div id="filter-custom-dates" class="form-grid" ${initialPeriod==='custom'?'':'hidden'}>${input('From','from',dateFrom,'date')}${input('To','to',dateTo,'date')}</div></form>`,`<button data-close>Cancel</button><button id="reset-more-filters">Reset</button><button id="apply-more-filters" class="primary">Apply filters</button>`,()=>{
  const form=$('#request-filters-form');
  form.elements.period.onchange=()=>{$('#filter-custom-dates').hidden=form.elements.period.value!=='custom';};
  $('#reset-more-filters').onclick=()=>{form.elements.kind.value='';form.elements.period.value='all';form.elements.from.value='';form.elements.to.value='';$('#filter-custom-dates').hidden=true;$('#form-error').textContent='';};
  const apply=()=>{if(!form.reportValidity())return;const fields=Object.fromEntries(new FormData(form));if(fields.period==='custom'&&fields.from&&fields.to&&fields.from>fields.to){$('#form-error').textContent='End date must be on or after start date.';form.elements.to.focus();return;}if(isProject)projectKind=fields.kind;else requestKind=fields.kind;datePeriod=fields.period;dateFrom=fields.from;dateTo=fields.to;selected=null;api.closeModal();api.refresh();$('[data-biz="filters"]')?.focus({preventScroll:true});};
  $('#apply-more-filters').onclick=apply;form.onsubmit=e=>{e.preventDefault();apply();};
 });
}
function projectRequestLink(r,label=r.title){return `<button class="text-btn workspace-request-link" data-project-request="${esc(r.id)}">${esc(label)} <span aria-hidden="true">↗</span></button>`;}
function projectOverview(project,requests){
 const active=requests.filter(r=>!['Draft','Withdrawn','Completed','Cancelled'].includes(r.stage));
 const complete=requests.filter(r=>r.stage==='Completed'),pending=requests.filter(r=>needsAction(r,state().actor));
 const events=requests.flatMap(r=>(r.history||[]).map(e=>({r,e}))).sort((a,b)=>b.e.at.localeCompare(a.e.at)).slice(0,5);
 return `${ledgerSummary(requests)}${projectCostSummary(project,requests)}<section class="project-team-strip" aria-label="Project team"><dl class="workspace-facts"><div><dt>Project Manager</dt><dd>${person(project.pm)}</dd></div><div><dt>Project Director</dt><dd>${person(project.director)}</dd></div><div><dt>Customer</dt><dd>${esc(project.customerId?name(project.customerId):'Internal project')}</dd></div><div><dt>Project status</dt><dd>${project.active?'Active':'Inactive'}</dd></div></dl></section><div class="workspace-project-grid"><section class="workspace-panel"><h2>Request progress</h2><div class="project-progress-values"><div><strong>${active.length}</strong><span>In progress</span></div><div><strong>${complete.length}</strong><span>Completed</span></div><div><strong>${requests.filter(r=>['Draft','Withdrawn'].includes(r.stage)).length}</strong><span>Draft / paused</span></div></div><button class="text-btn" data-project-tab="requests">View all project requests →</button></section><section class="workspace-panel"><h2>Your next actions <span class="workspace-count">${pending.length}</span></h2>${pending.length?pending.map(r=>`<div class="workspace-item"><div>${projectRequestLink(r)}<p>${esc(attentionText(r))}</p></div>${stageBadge(r)}</div>`).join(''):'<p class="muted">You are all caught up on this project.</p>'}</section><section class="workspace-panel workspace-activity"><h2>Recent activity</h2>${events.length?events.map(({r,e})=>`<div class="workspace-item"><div><strong>${esc(e.action)}</strong><p>${projectRequestLink(r)}</p><div class="workspace-event-by">${person(e.actor)}<time>${displayDate(e.at)}</time></div></div></div>`).join(''):'<p class="muted">Project activity will appear here as requests move forward.</p>'}</section></div>`;
}
function projectDocuments(requests){const rows=requests.filter(r=>requestDocs(r).length);return `<section class="workspace-panel"><h2>Contracts & Documents</h2>${rows.map(r=>`<article class="workspace-document-group"><header>${projectRequestLink(r)}${stageBadge(r)}</header>${documentRegister(r)}</article>`).join('')||'<p class="muted">No documents uploaded yet.</p>'}</section>`;}

function projectPayments(requests){
 const rows=scheduledPayments(requests),totals=ledgerTotals(requests);
 return `<section class="oa-totals workspace-payment-totals"><div><span>Paid · AUD</span><strong>${money(totals.paid)}</strong></div><div><span>Scheduled balance · AUD</span><strong>${money(totals.outstanding)}</strong></div><div><span>Overdue instalments</span><strong>${rows.filter(({payment:p})=>['Pending','Review','Ready'].includes(p.status)&&paymentDueDate(p)&&paymentDueDate(p)<date()).length}</strong></div></section><section class="workspace-panel"><h2>Payment schedule</h2>${rows.length?`<div class="workspace-payment-list">${rows.map(({request:r,payment:p,index})=>`<article class="workspace-payment-row"><div>${projectRequestLink(r)}<p>${index+1}. ${esc(p.label)}</p></div><div><span class="workspace-label">Due date</span><strong>${displayDate(paymentDueDate(p))}</strong>${['Pending','Review','Ready'].includes(p.status)&&paymentDueDate(p)&&paymentDueDate(p)<date()?'<span class="workspace-overdue">Overdue</span>':''}</div><div><span class="workspace-label">Status</span><strong>${esc(paymentReadiness(r,p).status)}</strong><small>${esc(p.method||'')}</small></div><strong class="workspace-payment-amount">${money(p.amount)}</strong></article>`).join('')}</div>`:'<div class="workspace-empty"><h3>No payment plan yet</h3><p>Scheduled instalments appear here once Finance sets a payment plan.</p></div>'}</section>`;
}
const confirmationLabel=v=>({Pending:'Awaiting confirmation',Approved:'Confirmed','Changes requested':'Changes requested',Declined:'Declined'}[v]||v);
function customerConfirmationBadge(status){return `<span class="customer-access-badge" data-confirmation="${esc(status)}">${esc(confirmationLabel(status))}</span>`;}
function projectCustomer(project,requests){
 const customer=data().customers?.find(c=>c.id===project.customerId),access=customerAccess(project),admin=role(state().actor)==='Admin';
 const services=requests.filter(r=>r.kind==='service'),reviews=services.filter(r=>r.customerReview?.customerId===project.customerId);
 const pending=reviews.filter(r=>r.stage==='Customer confirmation'&&r.customerReview.status==='Pending');
 const resolved=reviews.filter(r=>!pending.includes(r));
 const shared=services.filter(r=>r.customerContracts?.customerId===project.customerId&&r.customerContracts.files.length||r.customerReview?.customerId===project.customerId&&r.customerCompletion);
 const row=r=>`<div class="customer-confirmation-row"><div>${projectRequestLink(r)}<span class="customer-row-meta">${r.customerReview.decidedAt?displayDate(r.customerReview.decidedAt):'Requested '+displayDate(r.customerReview.requestedAt)} · ${money(r.customerReview.snapshot.amount)} AUD</span>${r.customerReview.comment?`<p>${esc(r.customerReview.comment)}</p>`:''}</div>${customerConfirmationBadge(r.customerReview.status==='Pending'&&r.stage!=='Customer confirmation'?'Paused':r.customerReview.status)}</div>`;
 return `<div class="customer-access-page"><header class="customer-access-heading"><div><h2>Customer Access</h2><p>People, confirmations and shared project information.</p></div><div class="customer-access-actions">${customer?.active&&access.enabled?`<button data-biz="customer-view-preview">${admin?'View customer portal':'Preview customer view'}</button>`:''}${admin&&customer?'<button data-biz="customer-access-settings">Manage access</button>':''}</div></header>
 <section class="workspace-panel customer-people"><div class="workspace-section-heading"><h2>People</h2>${admin?`<button class="primary" data-biz="project-invite" ${!project.active?'disabled title="Reactivate the project before sending an invitation."':''}>${!project.active?'Project inactive':customer?'Send invitation':'Invite customer'}</button>`:''}</div>${customer?`<div class="customer-person-row"><div class="customer-person-identity">${person(customer.id)}<div><strong>${esc(customer.contact||customer.name)}</strong><a href="mailto:${esc(customer.email)}">${esc(customer.email)}</a>${customer.contact&&customer.contact!==customer.name?`<span>${esc(customer.name)}</span>`:''}</div></div><div><span class="customer-field-label">Project role</span><strong>${access.role==='viewer'?'Viewer':'Approver'}</strong></div><div><span class="customer-field-label">Access</span><span class="customer-access-badge" data-confirmation="${customer.active&&access.enabled?'Approved':'Paused'}">${!customer.active?'Account inactive':access.enabled?'Active':'Paused'}</span></div>${admin?`<div class="customer-person-actions"><button data-edit-customer="${esc(customer.id)}">Edit contact</button><button data-password-customer="${esc(customer.id)}">Manage login</button></div>`:''}</div>${admin?'<p id="project-invitation-status" class="customer-invitation-status" role="status"></p>':''}<div class="customer-access-summary"><span><b>Visible services</b>${access.visibility==='all'?'All submitted project services':'Confirmation requests & shared contracts'}</span><span><b>New service requests</b>${access.defaultConfirmation?'Customer confirmation selected by default':'Internal approval by default'}</span><span><b>Documents</b>Only explicitly shared files</span></div>`:`<div class="customer-access-empty"><h3>No customer connected</h3><p>${admin?'Invite a customer or link an existing account in Project settings.':'Ask Admin to connect a customer to this project.'}</p>${admin?'<button data-biz="project-settings">Link existing customer</button>':''}</div>`}</section>
 <section class="workspace-panel customer-confirmations"><div class="workspace-section-heading"><h2>Pending confirmations <span class="workspace-count">${pending.length}</span></h2></div>${pending.length?pending.map(row).join(''):'<p class="customer-empty-inline">No confirmations waiting for the customer.</p>'}${resolved.length?`<details class="customer-resolved"><summary>Confirmation history <span>${resolved.length}</span></summary>${resolved.map(row).join('')}</details>`:''}</section>
 <section class="workspace-panel customer-shared"><div class="workspace-section-heading"><h2>Shared with customer <span class="workspace-count">${shared.length}</span></h2></div>${shared.length?shared.map(r=>`<article class="customer-shared-row"><div>${projectRequestLink(r)}${r.customerContracts?.customerId===project.customerId&&r.customerContracts.files.length?`<div class="customer-shared-group"><span class="customer-field-label">Contracts · ${displayDate(r.customerContracts.sharedAt)}</span>${documents(r.customerContracts.files)}</div>`:''}${r.customerCompletion&&r.customerReview?.customerId===project.customerId?`<div class="customer-shared-group"><span class="customer-field-label">Completed work · ${displayDate(r.customerCompletion.publishedAt)}</span><p>${esc(r.customerCompletion.summary)}</p>${documents(r.customerCompletion.files)}</div>`:''}</div>${canShareContracts(state(),r,state().actor)?`<button data-manage-shared="${esc(r.id)}">Manage files</button>`:''}</article>`).join(''):'<div class="customer-access-empty"><h3>No files shared yet</h3><p>Open a service request to share the selected supplier contract or publish completed work.</p><button data-project-tab="requests">View project requests</button></div>'}</section></div>`;
}
function customerAccessDialog(project){
 const a=customerAccess(project);
 formDialog('Manage customer access',`<p class="form-project-name">${esc(project.name)}</p><label class="customer-setting-check"><input type="checkbox" name="enabled" ${a.enabled?'checked':''}> Allow access to this project</label><label class="field">Project role<select name="role">${opts([['approver','Approver — view and confirm requests'],['viewer','Viewer — view only']],a.role)}</select></label><label class="field">Visible services<select name="visibility">${opts([['shared','Confirmation requests & shared contracts'],['all','All submitted project services']],a.visibility)}</select></label><fieldset class="customer-visible-fields"><legend>Customer-visible information</legend>${[['showBudget','Show budgets for project updates'],['showContracts','Show explicitly shared contracts'],['showCompletion','Show completion reports & files']].map(([key,label])=>`<label class="customer-setting-check"><input type="checkbox" name="${key}" ${a[key]?'checked':''}> ${label}</label>`).join('')}</fieldset><p class="muted">Confirmation requests always show the amount the customer is asked to approve. Reimbursements, internal notes, quotes and extracted bank details stay internal.</p><label class="customer-setting-check"><input type="checkbox" name="defaultConfirmation" ${a.defaultConfirmation?'checked':''}> Request customer confirmation by default</label><p class="muted">Applies to new service forms; the requester can change it before submission. Pending confirmations must be resolved or withdrawn before switching to Viewer or pausing access.</p>`,'Save access',fields=>command('customer-access',{projectId:project.id,data:{enabled:fields.enabled==='on',role:fields.role,visibility:fields.visibility,defaultConfirmation:fields.defaultConfirmation==='on',showBudget:fields.showBudget==='on',showContracts:fields.showContracts==='on',showCompletion:fields.showCompletion==='on'}}));
}
function previewProjectCustomer(project){
 if(role(state().actor)==='Admin')return api.openCustomerPreview(project.customerId,project.id);
 const customer=data().customers.find(c=>c.id===project.customerId);
 const visible=customerView(state(),customer.id).projects.find(p=>p.id===project.id);
 api.modal('Customer view — '+project.name,`<div class="customer-view-preview"><p class="customer-preview-notice">Read-only preview for ${esc(customer.contact||customer.name)}. Only customer-visible information is shown.</p>${visible?.requests.length?visible.requests.map(r=>`<details class="customer-preview-service"><summary><strong>${esc(r.review.snapshot.title)}</strong><span>${esc(r.status)}</span><b>${r.review.snapshot.amount==null?'Not shared':money(r.review.snapshot.amount)+' AUD'}</b></summary><dl><dt>Background</dt><dd>${esc(serviceBackground(r.review.snapshot))}</dd><dt>Delivery format</dt><dd>${esc(r.review.snapshot.approach)}</dd><dt>Progress</dt><dd>${esc(r.progress)}</dd></dl>${r.contracts?.files.length?`<h3>Shared contracts</h3>${documents(r.contracts.files)}`:''}${r.completion?`<h3>Completed work</h3><p>${esc(r.completion.summary)}</p>${documents(r.completion.files)}`:''}</details>`).join(''):'<div class="customer-access-empty"><h3>No services visible yet</h3><p>Customer confirmation requests and shared contracts will appear here.</p></div>'}</div>`,`<button data-close>Close preview</button>`);
}
export function businessPage(nextScope){
 if(nextScope==='suppliers')return suppliersPage(state());
 if(nextScope==='customers')return customersPage();
 if(nextScope==='home')return homePage();
 if(nextScope==='corporation'){nextScope='requests';requestProject='company';}
 if(scope!==nextScope){mobileDetail=false;scope=nextScope;selected=null;projectFilter='';search='';view='overview';projectSearch='';statusFilter='All';projectTab='overview';resetRequestDates();}
 if(scope==='projects'&&!data().projects.some(p=>p.id===projectFilter))projectFilter='';
 if(scope==='projects'&&!projectFilter)return projectsHome();
 const project=scope==='projects'?data().projects.find(p=>p.id===projectFilter):null;
 const allRequests=data().requests,projectRequests=project?allRequests.filter(r=>r.projectId===project.id):[];
 const requests=filterWorkspaceRequests(allRequests,{actor:state().actor,tab:project?'all':requestTab,project:project?.id||requestProject,kind:project?projectKind:requestKind,status:statusFilter,search,range:requestDateRange(datePeriod,dateFrom,dateTo),projects:data().projects});
 if(!mobileDetail&&!requests.some(r=>r.id===selected))selected=requests[0]?.id;
 const r=selectedRequest();if(!r)mobileDetail=false;
 const heading=`<header class="business-heading"><div>${project?'<button class="project-back" data-biz="project-home">← Projects</button>':''}<h1>${project?esc(project.name):'Requests'}</h1></div><div class="project-header-actions">${project&&isManager(state().actor)?'<button data-biz="project-settings">Project settings</button>':''}<button class="primary" data-biz="new-context">+ Request</button></div></header>`;
 const tabs=project?workspaceTabs(projectTabs,projectTab,'data-project-tab','Project sections'):workspaceTabs([['todo','To do',allRequests.filter(x=>needsAction(x,state().actor)).length],['created','Created by me',allRequests.filter(x=>x.requester===state().actor).length],['all','All requests',allRequests.length]],requestTab,'data-request-tab','Request views');
 const detailPage=`<div class="business-workspace oa-workspace mobile-detail-open"><section class="business-detail"><div class="oa-detail-back"><button class="business-mobile-back text-btn" data-biz="request-list">← Back to ${project&&projectTab!=='requests'?'project':'requests'}</button><span>${r?esc(r.reference):''}</span></div>${r?detail(r):''}</section></div>`;
 const projectPanel=()=>({overview:()=>projectOverview(project,projectRequests),documents:()=>projectDocuments(projectRequests),payments:()=>projectPayments(projectRequests),customer:()=>projectCustomer(project,projectRequests)})[projectTab]?.();
 return `<div id="business-page" class="business-page oa-ledger-page workspace-page ${mobileDetail?'detail-is-open':''}">${heading}${mobileDetail?detailPage:`${tabs}${project&&projectTab!=='requests'?projectPanel():`${requestFilters(project)}${ledgerSummary(requests)}<div class="business-workspace oa-workspace"><section class="business-list" aria-label="Business requests">${ledger(requests)}</section></div>`}`}</div>`;
}
function approvalRecord(r){
 const events=[...r.history].reverse();
 return `<aside class="oa-approval-record" aria-label="Approval record"><div class="approval-record-heading"><h3>Approval record</h3>${stageBadge(r)}</div><ol tabindex="0" aria-label="Approval history">${events.map(e=>`<li><strong>${esc(e.action)}</strong><div class="approval-event-meta">${person(e.actor)}<time>${displayDate(e.at)}</time></div>${e.detail?`<p>${esc(e.detail)}</p>`:''}</li>`).join('')||'<li>No activity yet</li>'}</ol></aside>`;
}

function detail(r){
 const actions=allowedActions(r,state().actor);
 const customer=r.customerReview;
 const customerState=customer&&({Approved:'Confirmed',Pending:'Awaiting confirmation','Changes requested':'Changes requested',Declined:'Declined'}[customer.status]||customer.status);
 const mainActions=actions.filter(a=>!['cancel','withdraw','escalate'].includes(a));
 const canShare=canShareContracts(state(),r,state().actor),hasMore=canShare||actions.includes('escalate');
 const actionBar=mainActions.length||hasMore?`<div class="business-actions request-action-bar request-header-actions" role="region" aria-label="Available request actions">${mainActions.map(a=>`<button data-biz="${a}" class="${['approve','submit','source','contract','plan','documents','paid','invoice','sign-contract','sign-variation','complete-service'].includes(a)?'primary':''}">${labels[a]}</button>`).join('')}${hasMore?`<details class="business-more"><summary>More</summary><div>${canShare?'<button data-biz="share-contracts">Share with customer</button>':''}${actions.includes('escalate')?`<button data-biz="escalate">${labels.escalate}</button>`:''}</div></details>`:''}</div>`:'';
 return `<div class="business-detail-head"><div><div class="request-heading-meta"><span>${esc(kinds[r.kind])}</span>${stageBadge(r)}</div><h2>${esc(r.title)}</h2></div><div class="request-total"><strong>${money(businessAmount(r))}</strong><span>${r.serviceContract?'Contract amount · AUD':r.selectedQuote?(r.quotes.find(q=>q.id===r.selectedQuote)?.priceMin!=null?'Supplier estimate ceiling · AUD':'Selected quote · AUD'):r.kind==='service'?'Requested budget · AUD':'AUD'}</span></div></div>
 <div class="request-summary-meta">${requestOwnership(r)}
 ${customer?`<details class="customer-confirmation-summary"><summary><strong>${customer.status==='Approved'?'✓ Customer confirmed':customer.status==='Pending'?'Customer confirmation pending':'Customer: '+esc(customerState)}</strong><span class="confirmation-expand" aria-hidden="true">⌄</span></summary><div><p>${esc(customer.customerName)} · Version ${customer.version} · ${money(customer.snapshot.amount)}</p>${customer.decidedAt?`<p>Decision on ${displayDate(customer.decidedAt)}</p>`:''}${customer.comment?`<p>${esc(customer.comment)}</p>`:''}${r.stage==='Customer confirmation'?'<p>Internal approval starts after the customer confirms.</p>':''}</div></details>`:''}
 ${r.directorNotice?`<div class="director-notice-summary"><strong>Director acknowledgement</strong><span>${person(r.directorNotice.recipient)} · ${r.directorNotice.acknowledgedAt?'Acknowledged · '+displayDate(r.directorNotice.acknowledgedAt):pendingDirectorNotice(r)?'Pending acknowledgement':'Inactive'}</span><span class="muted">For information only · Finance and payment can proceed</span></div>`:''}
 ${actionBar}
 ${['Budget review','Supplier review'].includes(r.stage)?`<div class="gate-progress">${Object.entries(gateReviewers(r)).map(([key,id])=>`<span>${person(id)}<b>${gateVotes(r)[key]?'✓ Approved':'Pending'}</b></span>`).join('')}</div>`:''}
 ${r.stage==='Returned'&&r.requester===state().actor?`<p class="request-return-note">${esc(attentionText(r))}</p>`:''}
 </div>
 <div class="request-detail-toolbar"><div class="business-tabs">${['overview',...(r.kind==='service'?['contracts']:[]),'documents','payments','activity'].map(v=>`<button data-business-view="${v}" class="${v===view?'active':''}">${v==='contracts'?'Quotes & contracts':v[0].toUpperCase()+v.slice(1)}${v==='documents'?' ('+requestDocs(r).length+')':v==='payments'?' ('+r.payments.length+')':''}</button>`).join('')}</div></div>
 <div class="oa-detail-body"><div class="business-content">${detailContent(r)}</div>${approvalRecord(r)}</div>${actions.some(a=>['withdraw','cancel'].includes(a))?`<footer class="request-danger-actions" aria-label="Request actions">${['withdraw','cancel'].filter(a=>actions.includes(a)).map(a=>`<button type="button" class="request-danger-button" data-biz="${a}">${labels[a]}</button>`).join('')}</footer>`:''}`;
}
function detailContent(r){
 const project=data().projects.find(p=>p.id===r.projectId);
 return `${view==='activity'?`<div class="request-record-meta">Execution: ${esc(r.executionVersion?.name||'v1')} · ${esc(r.reference)}${project?' · '+esc(project.name):''}</div><div class="timeline">${[...r.history].reverse().map(e=>`<article class="business-event"><strong>${esc(e.action)}</strong><small>${person(e.actor)} · ${new Date(e.at).toLocaleString('en-AU',{timeZone:'Australia/Melbourne'})}</small><p>${esc(e.detail)}</p></article>`).join('')}</div>`:view==='documents'?documentRegister(r):view==='contracts'?contracts(r):view==='payments'?payments(r):overview(r)}`;
}
function switchDetailView(nextView){
 if(nextView===view)return;
 const content=$('.business-content'),request=selectedRequest();
 if(!content||!request)return;
 // Keep the scroll range when a shorter tab replaces the overview. Updating only
 // this panel also preserves focus, expanded summaries and the surrounding UI.
 content.style.minHeight=`${Math.ceil(content.getBoundingClientRect().height)}px`;
 view=nextView;
 content.innerHTML=detailContent(request);
 document.querySelectorAll('[data-business-view]').forEach(button=>{
  button.classList.toggle('active',button.dataset.businessView===view);
 });
}
function changesSummary(r){
 const c=r.changeRequests?.at(-1);if(!c)return '';
 return `<section class="review-changes"><header><h3>${c.status==='open'?'Changes requested':'What changed'}</h3><span>${person(c.by)} · ${displayDate(c.at)}</span></header><p>${esc(c.reason)}</p>${c.status==='open'?`<p class="muted">Assigned to ${esc(name(c.assignedTo))}. Update the request and resubmit.</p>`:`<p class="muted">Resubmitted ${displayDate(c.resubmittedAt)}</p>${c.changes?.length?`<dl class="overview-list">${c.changes.map(x=>`<div class="overview-row"><dt>${esc(x.label)}</dt><dd><del>${esc(x.before??'Not recorded')}</del><strong>${esc(x.after??'Not recorded')}</strong></dd></div>`).join('')}</dl>`:'<p>No tracked fields changed. Review the response before approving.</p>'}`}</section>`;
}
function reviewSummary(r){
 if(r.kind!=='service')return '';
 const q=r.quotes.find(q=>q.id===r.selectedQuote),c=r.serviceContract;
 const mismatch=q&&r.approvedBudget!=null&&q.amount>r.approvedBudget||c&&q&&(q.priceMin!=null?c.amount<q.priceMin||c.amount>q.amount:Math.abs(c.amount-q.amount)>.009);
 const facts=[['Approved budget',r.approvedBudget!=null?money(r.approvedBudget):'Pending approval'],[r.finalSupplier||r.serviceContract?'Final supplier':r.pendingFinalSupplier?'Proposed supplier':'Preferred supplier',q?`${q.supplier} · ${quotePrice(q)}`:'Not selected'],['Contract amount',c?money(c.amount):'Not uploaded'],['Supplier ABN',(c?.abn||q?.abn||'Not found')+' · '+(c?.abnCheck?.status==='checked'?'Checked':c?.abnCheck?'Needs review':'Not checked')],['Bank details',(c?.bankDetails!==undefined?c.bankDetails.trim():c?.analysis?.report?.bankDetails?.trim())||(c?.analysis?'Not found':'Not checked')]];
 const points=c?.analysis?.report?.attentionPoints;if(points?.length)facts.push(['AI review points',`${points.filter(p=>p.severity==='High').length} high priority · ${points.length} total — see Quotes & contracts`]);
 return `<section class="review-summary"><h3>Review summary</h3>${mismatch?'<p class="request-return-note">Amount mismatch — check the approved budget, selected quote and contract before continuing.</p>':''}<dl class="overview-list">${facts.map(([k,v])=>`<div class="overview-row"><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></section>`;
}
function overview(r){
 const row=(label,value,format='')=>`<div class="overview-row ${format}"><dt>${esc(label)}</dt><dd>${esc(value||'—')}</dd></div>`;
 const personRow=(label,id)=>`<div class="overview-row"><dt>${esc(label)}</dt><dd>${person(id)}</dd></div>`;
 const basics=r.kind==='service'
  ?row('Background (why is this needed?)',serviceBackground(r))+row('Delivery format',r.approach)+row('Requested budget',money(r.amount),'amount-row')+(r.budgetChange?row('Budget increase requested',money(r.budgetChange),'amount-row'):'')
  :(r.invoiceDate?row('Expense date',r.invoiceDate):'')+(r.invoiceReference?row('Invoice reference',r.invoiceReference):'');
 const owners=(r.supervisor?personRow('Supervisor',r.supervisor):'')+(r.kind!=='corporation'&&r.route?personRow('PM',r.route.pm)+personRow('Director',r.route.director)+(r.kind==='reimbursement'?(r.reimbursementFlowVersion===2?row('Director acknowledgement','Above AUD 2,000 · Does not hold payment'):row('Director review',r.route.threshold==null?'Manual only':money(r.route.threshold)+' and above'))+row('Finance review','Before payment'):''):'');
 const approvals=r.kind==='corporation'?row('Admin approval',r.decisions.includes('alex')?'Approved':'Pending')+row('Finance approval',r.decisions.includes('jamie')?'Approved':'Pending'):'';
 return `${changesSummary(r)}${reviewSummary(r)}${serviceControlSummary(r)}${invoiceSummary(r,documents)}${expenseSupplierSummary(r)}<dl class="overview-list">${basics}${owners}${approvals}${r.attachments.length?`<div class="overview-row"><dt>Attachments</dt><dd>${documents(r.attachments)}</dd></div>`:''}</dl>`;
}
function contracts(r){
 return `${serviceControlSummary(r)}${invoiceSummary(r,documents)}${serviceContractSummary(r)}${r.quotes.length?`<div class="business-section"><h3>Supplier comparison</h3><div class="xero-table-wrap"><table class="xero-table quote-comparison-table"><thead><tr><th scope="col">Supplier</th><th scope="col">Selection</th><th scope="col" class="amount-column">Price / range · AUD</th><th scope="col">Service content</th><th scope="col">Documents</th></tr></thead><tbody>${r.quotes.map(q=>`<tr class="${q.id===r.selectedQuote?'selected-quote':''}"><td data-label="Supplier"><strong>${esc(q.supplier)}</strong></td><td data-label="Selection">${q.id===r.selectedQuote?`<span class="supplier-badge checked">${r.finalSupplier||r.serviceContract?'Final supplier':r.pendingFinalSupplier?'Proposed supplier':'Preferred'}</span>`:q.id===r.preferredQuote?'<span class="supplier-badge">Preferred</span>':'—'}</td><td data-label="Price / range · AUD" class="amount-column"><strong>${quotePrice(q)}</strong>${q.priceMin!=null?'<span class="table-secondary">Estimated · upper limit for approval</span>':''}</td><td data-label="Service content" class="proposal-scope">${esc(q.serviceScope)||'See attached quote'}</td><td data-label="Documents">${q.quoteFiles.length||q.contractFiles.length?`<details class="quote-document-details"><summary>Quote${q.id===r.selectedQuote&&r.serviceContract?'':' & contract'} documents</summary><div class="quote-document-content"><h4>Quote</h4>${documents(q.quoteFiles)}${q.id===r.selectedQuote&&r.serviceContract?'':`<h4>Contract / draft contract</h4>${documents(q.contractFiles)}${abnSummary(q.abnCheck)}`}</div></details>`:'No attachment'}</td></tr>`).join('')}</tbody></table></div><dl class="request-facts quote-selection-reason"><div><dt>Selection reason</dt><dd>${esc(r.selectionReason)||'Not provided'}</dd></div></dl></div>`:''}${!r.quotes.length?'<div class="oa-panel-empty"><h3>No quotes or contracts yet</h3><p>Supplier documents are prepared after pre-approval.</p></div>':''}`;
}
function payments(r){
 const totals=paymentTotals(r);
 return `<div class="oa-payment-totals"><div><span>Paid · AUD</span><strong>${money(totals.paid)}</strong></div><div><span>Scheduled balance · AUD</span><strong>${totals.scheduled?money(totals.outstanding):'Not scheduled'}</strong></div></div>${r.payments.length?`<div class="business-section"><h3>Payment schedule</h3><div class="xero-table-wrap"><table class="xero-table payment-schedule-table"><thead><tr><th scope="col">Milestone</th><th scope="col">Due date</th><th scope="col">Method</th><th scope="col">Status</th><th scope="col" class="amount-column">Amount · AUD</th></tr></thead><tbody>${r.payments.map((p,i)=>{const ready=paymentReadiness(r,p);return `<tr class="${ready.current?'current-instalment':''}"><td data-label="Milestone"><strong>${i+1}. ${esc(p.label)}</strong>${p.kind?`<small class="table-secondary">${esc(p.kind)}</small>`:''}${ready.final||ready.current?`<small class="table-secondary">${[ready.final?'Final payment':'',ready.current?'Current instalment':''].filter(Boolean).join(' · ')}</small>`:''}</td><td data-label="Due date">${displayDate(paymentDueDate(p))}</td><td data-label="Method">${esc(p.method)||'Not specified'}</td><td data-label="Status"><span class="oa-stage" data-approval-status="${esc(ready.status)}">${esc(ready.status)}</span></td><td data-label="Amount · AUD" class="amount-column"><strong>${money(p.amount)}</strong></td></tr><tr class="payment-evidence-row"><td colspan="5"><details class="payment-evidence"><summary>Checklist & documents · ${esc(p.label)}</summary><div class="payment-evidence-content"><ul class="payment-checklist">${ready.items.map(x=>`<li class="${x.done?'done':''}"><span aria-hidden="true">${x.done?'✓':'○'}</span> ${esc(x.label)}</li>`).join('')}</ul><dl class="request-facts"><div><dt>Requirements</dt><dd>${esc(p.requirements)||'Not specified'}</dd></div>${p.invoiceNumber?`<div><dt>Invoice / claim</dt><dd>${esc(p.invoiceNumber)} · received ${esc(p.receivedDate)}</dd></div><div><dt>Contractual due date</dt><dd>${esc(p.invoiceDueDate)}</dd></div>${p.responseDueDate?`<div><dt>Response deadline</dt><dd>${esc(p.responseDueDate)}</dd></div>`:''}<div><dt>PM verification</dt><dd>${p.pmReview?person(p.pmReview.by)+' · '+esc(p.pmReview.note):'Pending'}</dd></div>`:''}${p.acceptance?`<div><dt>Acceptance</dt><dd>${esc(p.acceptance.summary)}<div class="table-secondary">${p.acceptance.approvedBy?'Approved by '+person(p.acceptance.approvedBy):'Awaiting Director'}</div></dd></div>`:''}${p.paymentReference?`<div><dt>Payment record</dt><dd>Paid ${esc(p.paidAt)}<div class="table-secondary">Reference ${esc(p.paymentReference)}</div></dd></div>`:''}</dl><h4>Supporting documents</h4>${documents(p.files)}${p.acceptance?`<h4>Acceptance documents</h4>${documents(p.acceptance.files)}`:''}${p.paymentReference?`<h4>Payment proof</h4>${documents(p.proof)}`:''}</div></details></td></tr>`;}).join('')}</tbody></table></div><p class="muted">Payment records are manual; this workspace does not send money.</p></div>`:'<div class="oa-panel-empty"><h3>No payment plan yet</h3><p>Finance sets milestones after contract approval.</p></div>'}`;
}
function documentRegister(r){
 const rows=requestDocumentRows(r),current=rows.filter(x=>!x.historical),earlier=rows.filter(x=>x.historical);
 const list=items=>`<div class="document-register">${items.map(x=>`<article class="document-register-row"><div>${documents([x.file])}<span>${esc(x.category)} · ${esc(x.version)}</span></div><span class="document-visibility">${x.shared?(customerAccess(data().projects.find(p=>p.id===r.projectId)).enabled&&customerAccess(data().projects.find(p=>p.id===r.projectId))[x.category==='Completion'?'showCompletion':'showContracts']?'Shared with customer':'Customer sharing paused'):'Internal'}</span></article>`).join('')}</div>`;
 return rows.length?`${list(current)}${earlier.length?`<details class="document-history"><summary>Earlier versions (${earlier.length})</summary>${list(earlier)}</details>`:''}`:'<div class="oa-panel-empty"><h3>No documents yet</h3></div>';
}

async function readFiles(id){const form=$('#business-form');const list=[...($(id)?.files||[])];if(list.reduce((n,f)=>n+f.size,0)>3*1024*1024)throw new Error('Choose files totalling less than 3 MB.');const files=await Promise.all(list.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read file.'));reader.onload=()=>resolve({name:f.name,size:f.size,type:f.type,data:reader.result});reader.readAsDataURL(f);})));if(!form?.isConnected)throw new Error('Upload cancelled.');return files;}
function formDialog(title,body,button,save,setup,secondary){api.modal(title,`<form id="business-form" class="business-form">${body}</form>`,`<button data-close>Cancel</button>${secondary?'<button id="business-draft">Save draft</button>':''}<button class="primary" id="business-save">${button}</button>`,()=>{const form=$('#business-form');setup?.(form);let busy=false;const run=async draft=>{if(busy||!form.reportValidity())return;busy=true;const actor=state().actor;$('#business-save').disabled=true;if($('#business-draft'))$('#business-draft').disabled=true;try{await save(Object.fromEntries(new FormData(form)),actor,draft);if(!form.isConnected)return;api.closeModal();api.refresh();}catch(e){busy=false;if(form.isConnected){$('#form-error').textContent=e.message;$('#business-save').disabled=false;if($('#business-draft'))$('#business-draft').disabled=false;}}};$('#business-save').onclick=()=>run(false);if(secondary)$('#business-draft').onclick=()=>run(true);form.onsubmit=e=>{e.preventDefault();run(false);};});}
const command=(operation,data={})=>api.command({operation,...data});
const act=(r,action,data={})=>command('action',{id:r.id,action,data});
export function openBusinessRequest(existing=null,imported=null){
 if(existing)return requestForm(existing,imported);
 if(!canCreateCompanyExpense(state().actor))return projectRequestChoice();
 api.modal('Request',`<div class="request-choices"><button class="request-choice" data-request-category="corporation"><span class="choice-symbol">↗</span><strong>Company Expenses</strong><span>Reimbursements & daily expenses</span></button><button class="request-choice" data-request-category="project"><span class="choice-symbol">▱</span><strong>Projects</strong><span>Reimbursement or service</span></button></div>`,'',()=>{document.querySelectorAll('[data-request-category]').forEach(b=>b.onclick=()=>b.dataset.requestCategory==='corporation'?requestForm({kind:'corporation'}):projectRequestChoice());});
}
function projectRequestChoice(contextual=false){
 const projects=data().projects.filter(p=>p.active);
 const current=contextual&&projectFilter?data().projects.find(p=>p.id===projectFilter):null;
 if(contextual&&projectFilter&&!current?.active){
  api.modal('Project request',`${current?`<div class="form-project-name">${esc(current.name)}</div>`:''}<p>${current?'This project is inactive. Reactivate it in Project settings before creating a request.':'This project is no longer available.'}</p>`,'<button data-close>Cancel</button>');
  return;
 }
 api.modal('Project request',`${projects.length?`${current?`<div class="form-project-name">${esc(current.name)}</div>`:`<label class="field">Project<select id="request-project">${opts([['','Select a project'],...projects.map(p=>[p.id,p.name])],'')}</select></label>`}<div class="request-choices"><button class="request-choice" data-project-kind="reimbursement"><strong>Reimbursement</strong><span>SMALL expenses already incurred</span></button><button class="request-choice" data-project-kind="service"><strong>Service</strong><span>Request approval before BIG expenses</span></button></div>`:'<p>No active projects. Create a project first.</p>'}`,`<button id="request-choice-back">${contextual?'Cancel':'Back'}</button>${!projects.length&&isManager(state().actor)?'<button id="request-create-project" class="primary">New project</button>':''}`,()=>{
  $('#request-choice-back').onclick=()=>contextual?api.closeModal():openBusinessRequest();if($('#request-create-project'))$('#request-create-project').onclick=()=>projectDialog();
  document.querySelectorAll('[data-project-kind]').forEach(b=>b.onclick=()=>{const id=current?.id||$('#request-project').value;if(!id){$('#form-error').textContent='Select a project.';$('#request-project').focus();return;}requestForm({kind:b.dataset.projectKind,projectId:id});});
 });
}
function requestForm(existing={},imported=null){
 const editing=!!existing.id,kind=existing.kind||'corporation',service=kind==='service',project=data().projects.find(p=>p.id===existing.projectId);
 if(kind==='corporation'&&!canCreateCompanyExpense(state().actor)){api.notify('Only PM, Admin, Finance and Directors can submit company expenses.');return;}
 let retained=existing.attachments|| (imported?[imported.attachment]:[]);
 const amount=expenseAmount(existing);let supplierCheck=existing.supplierAbnCheck||null;
 const body=`${project?`<div class="form-project-name">${esc(project.name)}</div>`:''}${service?`${input('Service','title',existing.title||'','text','required maxlength="160"')}${area('Background (why is this needed?)','background',serviceBackground(existing))}${area('Delivery format','approach',existing.approach)}${input('Estimated budget · AUD','amount',amount,'number','required min="0.01" max="1000000000" step="0.01"')}${input('Paying legal entity','payingEntity',existing.payingEntity||project?.payingEntity||'','text','required maxlength="200"')}<label class="field">Cost code<select name="costCode">${opts(costCodes.map(k=>[k,k]),existing.costCode||'Professional services')}</select></label><div class="customer-confirmation-choice"><label><input type="checkbox" name="notifyCustomer" ${(existing.notifyCustomer??(editing?!!project?.customerId:customerAccess(project).defaultConfirmation))?'checked':''} ${!project?.customerId?'disabled':''}> Notify customer and request confirmation</label><p class="muted">${project?.customerId?'Unchecked: go directly to internal Director / Finance approval. Checked: wait for customer confirmation first.':'Assign a customer in project settings to enable customer confirmation. Internal approval applies by default.'}</p></div>`:`${input('Expense name','title',existing.title||'','text','required maxlength="160" placeholder="e.g. Office supplies or travel expenses"')}<div class="form-grid">${input('Amount · AUD','amount',amount,'number','required min="0.01" max="1000000000" step="0.01"')}${input('Expense date','invoiceDate',existing.invoiceDate||existing.date||date(),'date','required')}</div>${upload('Invoice / receipt','business-evidence')}${retained.length?documents(retained):''}<button type="button" class="text-btn scan-in-form" id="scan-reimbursement">Scan invoice</button>${expenseSupplierFields(existing)}`}`;
 formDialog(editing?'Edit request':service?'Project service':kind==='corporation'?'Company expense':'Project reimbursement',body,'Submit',async(fields,actor,draft)=>{
   const attachments=service?retained:[...retained,...await readFiles('#business-evidence')];
   const result=await command('request',{id:editing?existing.id:undefined,data:{...existing,...fields,...(service?{purpose:'',notifyCustomer:fields.notifyCustomer==='on'}:{supplierCheckId:supplierCheck?.id||''}),kind,attachments},submit:!draft});selected=result.id;mobileDetail=true;statusFilter='All';resetRequestDates();scope=scope==='projects'&&result.projectId?'projects':'requests';projectFilter=scope==='projects'?result.projectId:'';projectTab='requests';requestTab='created';requestProject='';requestKind='';projectKind='';search='';view='overview';api.navigate(scope);
 },form=>{if(!service){const result=form.querySelector('#expense-abn-result'),supplier=form.elements.supplier,abn=form.elements.supplierAbn,button=form.querySelector('#expense-check-abn');let generation=0;const clear=()=>{generation++;supplierCheck=null;result.innerHTML='<p class="muted">ABN not checked.</p>';};supplier.oninput=clear;abn.oninput=clear;button.onclick=async()=>{const ticket=++generation;button.disabled=true;result.textContent='Checking ABN…';try{const check=await requestApi('/api/expenses/check-abn',{method:'POST',data:{supplier:supplier.value,abn:abn.value}});if(ticket!==generation||!form.isConnected)return;supplierCheck=check;result.innerHTML=abnSummary(check);}catch(e){if(ticket===generation&&form.isConnected){supplierCheck=null;result.textContent=e.message;}}finally{if(form.isConnected)button.disabled=false;}};}if($('#scan-reimbursement'))$('#scan-reimbursement').onclick=async()=>{try{const fields=Object.fromEntries(new FormData(form)),files=await readFiles('#business-evidence');api.scan((invoice,attachment)=>requestForm({...existing,...fields,kind,...importedExpense(invoice),attachments:[...retained,...files,attachment]}),()=>requestForm({...existing,...fields,kind,supplierAbnCheck:supplierCheck,attachments:[...retained,...files]}));}catch(e){$('#form-error').textContent=e.message;}};},true);
}
function projectDialog(project){formDialog(project?'Project settings':'New project',`${input('Project name','name',project?.name,'text','required maxlength="120"')}${input('Paying legal entity','payingEntity',project?.payingEntity||'','text','maxlength="200"')}${input('Project budget · AUD (optional)','budget',project?.budget??'','number','min="0.01" max="1000000000" step="0.01"')}<label class="field">Customer<select name="customerId">${opts([['','Internal project / no customer'],...(data().customers||[]).filter(c=>c.active||c.id===project?.customerId).map(c=>[c.id,c.name])],project?.customerId||'')}</select></label><p class="muted">Choose whether customer confirmation is required on each service request. Use Invite customer inside the project to create a login and email the credentials.</p><div class="form-grid"><label class="field">Responsible PM<select name="pm">${opts(users.filter(u=>u.role==='PM'&&!u.inactive).map(u=>[u.id,u.name]),project?.pm)}</select></label><label class="field">Project Director<select name="director">${opts(users.filter(u=>u.role==='Director').map(u=>[u.id,u.name]),project?.director)}</select></label></div><p class="muted">Project reimbursements go to the project PM, then Finance. Expenses above AUD 2,000 also require Director acknowledgement, without holding payment.</p><label class="field">Project members<select name="members" multiple size="5">${users.filter(u=>!u.inactive&&['Employee','PM','Director'].includes(u.role)).map(u=>`<option value="${esc(u.id)}" ${(project?.members||[]).includes(u.id)?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label>${project?`<label><input name="active" type="checkbox" ${project.active?'checked':''}> Active project</label>`:''}`,'Save project',fields=>command('project',{data:{...fields,members:[...document.querySelector('[name=members]').selectedOptions].map(o=>o.value),threshold:project?project.threshold:10000,id:project?.id,active:project?fields.active==='on':true}}));}
function projectList(){api.modal('Projects',`<div class="project-list">${data().projects.map(p=>`<div><strong>${esc(p.name)}${p.active?'':' · Inactive'}</strong><p>${person(p.pm)} · ${person(p.director)} · Director FYI above AUD 2,000</p><button data-edit-project="${p.id}">Edit</button></div>`).join('')||'<p>No projects yet.</p>'}</div>`,`<button data-close>Close</button><button id="add-project" class="primary">New project</button>`,()=>{$('#add-project').onclick=()=>projectDialog();document.querySelectorAll('[data-edit-project]').forEach(b=>b.onclick=()=>projectDialog(data().projects.find(p=>p.id===b.dataset.editProject)));});}
function sourceDialog(r){
 let rows=r.quotes.length?r.quotes.map(q=>({...q})): [{supplier:'',amount:'',quoteFiles:[],contractFiles:[]}];
 const row=(q,i)=>`<fieldset class="supplier-row"><legend>Supplier ${i+1}</legend><div class="form-grid">${input('Supplier name',`supplier-${i}`,q.supplier,'text','required')}</div><div class="form-grid">${input('Minimum price · AUD incl. GST',`priceMin-${i}`,q.priceMin??q.amount,'number','required min="0.01" step="0.01"')}${input('Maximum price · AUD incl. GST',`amount-${i}`,q.amount,'number','required min="0.01" step="0.01"')}</div>${area('Service content',`serviceScope-${i}`,q.serviceScope||'')}${upload('Quote attachment (optional)',`quote-${i}`)}${documents(q.quoteFiles)}<label><input type="radio" name="selectedIndex" value="${i}" ${q.id&&q.id===r.selectedQuote||!r.selectedQuote&&i===0?'checked':''} required> Preferred</label><button type="button" data-remove-supplier="${i}">Remove supplier</button></fieldset>`;
 formDialog('Supplier proposals',`<div id="supplier-rows">${rows.map(row).join('')}</div><button type="button" id="add-supplier">+ Add supplier</button>${area('Why choose this supplier?','reason',r.selectionReason)}`,'Send for review',async(fields)=>{
  const quotes=await Promise.all(rows.map(async(q,i)=>!q?null:{id:q.id,sourceIndex:i,supplier:fields[`supplier-${i}`],amount:fields[`amount-${i}`],priceMin:fields[`priceMin-${i}`],serviceScope:fields[`serviceScope-${i}`],quoteFiles:[...q.quoteFiles,...await readFiles(`#quote-${i}`)],contractFiles:q.contractFiles||[]}));
  const active=quotes.filter(Boolean);await act(r,'source',{supplierSelectionVersion:1,quotes:active,selectedIndex:active.findIndex(q=>q.sourceIndex===Number(fields.selectedIndex)),reason:fields.reason});
 },form=>{form.onclick=e=>{if(e.target.hasAttribute('data-remove-supplier')){const i=Number(e.target.dataset.removeSupplier);rows[i]=null;e.target.closest('fieldset').remove();}};$('#add-supplier').onclick=()=>{const i=rows.length;rows.push({supplier:'',amount:'',quoteFiles:[],contractFiles:[]});$('#supplier-rows').insertAdjacentHTML('beforeend',row(rows[i],i));};});
}
function planDialog(r){let count=1;const row=(i)=>`<fieldset class="payment-row" data-payment-row="${i}"><legend>Payment ${i+1}</legend><div class="form-grid">${input('Milestone','label-'+i,i?'':'Full payment','text','required')}${input('Amount · AUD','amount-'+i,i?'':businessAmount(r),'number','required min="0.01" step="0.01"')}${input('Expected date','dueDate-'+i,date(),'date','required')}<label class="field">Method<select name="method-${i}">${opts(['Bank transfer','Card','BPAY','Other'].map(v=>[v,v]))}</select></label></div>${area('Required documents','requirements-'+i,'Invoice and evidence of delivery / completion')}${i?`<button type="button" data-remove-payment="${i}">Remove payment</button>`:''}</fieldset>`;
formDialog('Payment plan',`<p>Approved total: <strong>${money(businessAmount(r))}</strong></p><p class="muted">The last instalment requires acceptance evidence and Director approval.</p><div id="payment-rows">${row(0)}</div><button type="button" id="add-payment">+ Add instalment</button><p id="payment-balance" class="muted"></p>`,'Approve payment plan',fields=>{const payments=[...document.querySelectorAll('[data-payment-row]')].map(el=>{const i=el.dataset.paymentRow;return Object.fromEntries(['label','amount','dueDate','method','requirements'].map(k=>[k,fields[`${k}-${i}`]]));});return act(r,'plan',{payments});},form=>{const balance=()=>{const sum=[...form.querySelectorAll('[name^="amount-"]')].reduce((n,el)=>n+Number(el.value),0);$('#payment-balance').textContent=`Scheduled ${money(sum)} · Remaining ${money(businessAmount(r)-sum)}`;};form.oninput=balance;form.onclick=e=>{if(e.target.dataset.removePayment){e.target.closest('fieldset').remove();balance();}};$('#add-payment').onclick=()=>{$('#payment-rows').insertAdjacentHTML('beforeend',row(count++));balance();};balance();});}
async function simpleAction(action,r){if(invoiceDialog(action,r,{formDialog,input,area,upload,readFiles,act,date,documents}))return;if(serviceActionDialog(action,r,{formDialog,input,area,upload,readFiles,act,date,documents}))return;if(action==='acknowledge')return formDialog('Acknowledge expense',`<p>${esc(r.title)} · <strong>${money(r.directorNotice.amount)}</strong></p><p>Confirm that you have seen this project expense. This is not an approval and does not hold Finance or payment.</p>`,'Confirm acknowledgement',()=>act(r,'acknowledge'));if(action==='lodge')return formDialog('Publish completed work',`<p>These details and files will be visible to the project customer.</p>${area('Completion summary','summary',r.customerCompletion?.summary||'')}${upload('Customer-facing documents','completion-files')}${r.customerCompletion?.files?.length?'<label><input type="checkbox" name="keepFiles" checked> Keep previously published files</label>':''}`,'Publish to customer',async fields=>act(r,'lodge',{summary:fields.summary,files:[...(fields.keepFiles==='on'?r.customerCompletion?.files||[]:[]),...await readFiles('#completion-files')]}));if(action==='edit')return openBusinessRequest(r);if(action==='contract')return openContractDialog(r,api);if(action==='source')return sourceDialog(r);if(action==='plan')return isServiceV2(r)?servicePlanDialog(r,{formDialog,input,area,act,date}):planDialog(r);if(action==='submit'){await act(r,action);return api.refresh();}if(action==='approve'&&directorPaymentPending(r)){return formDialog('Approve last project payment',`<p>${esc(currentPayment(r).label)} · <strong>${money(currentPayment(r).amount)}</strong></p><p>Project Director confirmation is required before Finance can release the last payment.</p><p>${['Deposit / advance','Progress'].includes(currentPayment(r).kind)?'This confirms payment release. Completion acceptance remains a separate step.':'Review the completion and payment evidence.'}</p>${documents(currentPayment(r).files)}`,'Approve payment',()=>act(r,'approve'));}if(action==='approve'){formDialog('Approve '+r.stage,`<p>${esc(r.title)} · <strong>${money(businessAmount(r))}</strong></p>${['Payment review','Final acceptance'].includes(r.stage)?`<p>${esc(currentPayment(r).label)} · ${money(currentPayment(r).amount)}</p>${documents(currentPayment(r).files)}`:''}${r.stage==='Final acceptance'?`<h3>Acceptance</h3><p>${esc(currentPayment(r).acceptance?.summary)}</p>${documents(currentPayment(r).acceptance?.files)}`:''}<p>${r.stage==='Final acceptance'?'Confirm the service has been completed and accepted.':r.stage==='Contract review'?'Review the service contract, Requester notes, ABN findings and payment terms. Approval allows the requester to record the signed contract before payment setup.':'Record your approval.'}</p>`,'Approve',()=>act(r,'approve'));return;}if(action==='documents'){const p=currentPayment(r);return formDialog('Payment documents',`<p><strong>${esc(p.label)} · ${money(p.amount)}</strong></p><p>Expected ${esc(paymentDueDate(p))} · ${esc(p.method)}</p><p>Required: ${esc(p.requirements)}</p>${serviceInvoiceFields(r,input,date)}${upload('Invoice / payment documents','payment-files')}${area('Notes','note')}${isFinalPayment(r)?`<div class="final-payment-fields"><h3>Final payment acceptance</h3>${area('What was completed and accepted?','acceptanceSummary')}${upload('Acceptance evidence','acceptance-files')}</div>`:''}`,'Submit documents',async(fields,actor)=>{const files=await readFiles('#payment-files'),acceptanceFiles=isFinalPayment(r)?await readFiles('#acceptance-files'):[];await act(r,'documents',{...fields,files,acceptanceFiles});});}if(action==='paid')return formDialog('Record completed payment',`<p>${esc(currentPayment(r).label)} · <strong>${money(currentPayment(r).amount)}</strong></p><p class="muted">Record a payment already made outside this workspace.</p>${r.kind!=='service'?`<label class="field">Payment method<select name="method">${opts(['Bank transfer','Card','BPAY','Other'].map(v=>[v,v]))}</select></label>`:''}${input('Payment reference','reference','','text','required')}${input('Actual payment date','date',date(),'date','required')}${upload('Payment receipt / bank confirmation','paid-files')}`,'Record payment',async(fields,actor)=>{const files=await readFiles('#paid-files');await act(r,'paid',{...fields,files});});
const body=`${action==='escalate'?`<label class="field">Project Director<select name="director">${opts(users.filter(u=>u.role==='Director'&&u.id!==r.requester).map(u=>[u.id,u.name]),r.route?.director)}</select></label>`:''}${action==='withdraw'?'<p>Review and payment actions are paused. You can resubmit or edit and restart approval.</p>':''}${action==='cancel'?'<p>This closes the request and cancels unpaid instalments. Recorded payments remain in the audit trail.</p>':''}${area('Reason','reason')}`;formDialog(labels[action],body,labels[action],fields=>act(r,action,fields));}
export function bindBusiness(){const root=$('#business-page');if(!root)return;root.querySelectorAll('[data-preview-customer]').forEach(b=>b.onclick=()=>api.openCustomerPreview(b.dataset.previewCustomer));root.querySelectorAll('[data-home-tab]').forEach(b=>b.onclick=()=>{homeTab=b.dataset.homeTab;api.refresh();});bindSuppliers({...api,openRequest:openSavedRequest,openProjects:()=>{showProjects();api.navigate('projects');api.refresh({resetScroll:true});}});void customerMailState();void projectInvitationState();root.querySelectorAll('[data-manage-shared]').forEach(b=>b.onclick=()=>shareContractsDialog(data().requests.find(r=>r.id===b.dataset.manageShared)));root.querySelectorAll('[data-clear-filter]').forEach(b=>b.onclick=()=>{const key=b.dataset.clearFilter;if(key==='project'||key==='all')requestProject='';if(key==='kind'||key==='all'){if(scope==='projects')projectKind='';else requestKind='';}if(key==='status'||key==='all')statusFilter='All';if(key==='date'||key==='all')resetRequestDates();if(key==='search'||key==='all')search='';selected=null;api.refresh();$('[data-biz="filters"]')?.focus({preventScroll:true});});root.querySelectorAll('[data-request-tab]').forEach(b=>b.onclick=()=>{requestTab=b.dataset.requestTab;mobileDetail=false;selected=null;api.refresh();});root.querySelectorAll('[data-project-tab]').forEach(b=>b.onclick=()=>{projectTab=b.dataset.projectTab;mobileDetail=false;selected=null;api.refresh({resetScroll:true});});root.querySelectorAll('[data-project-request]').forEach(b=>b.onclick=()=>{ledgerScroll=root.scrollTop;selected=b.dataset.projectRequest;view='overview';mobileDetail=true;api.refresh({resetScroll:true});});if($('#workspace-project'))$('#workspace-project').onchange=e=>{requestProject=e.target.value;selected=null;api.refresh();};if($('#workspace-kind'))$('#workspace-kind').onchange=e=>{if(scope==='projects')projectKind=e.target.value;else requestKind=e.target.value;selected=null;api.refresh();};root.querySelectorAll('[data-password-customer]').forEach(b=>b.onclick=()=>customerPasswordDialog(data().customers.find(c=>c.id===b.dataset.passwordCustomer)));root.querySelectorAll('[data-edit-customer]').forEach(b=>b.onclick=()=>customerDialog(data().customers.find(c=>c.id===b.dataset.editCustomer)));root.querySelectorAll('[data-invite-customer]').forEach(b=>b.onclick=()=>projectInviteDialog(null,data().customers.find(c=>c.id===b.dataset.inviteCustomer)));root.querySelectorAll('[data-open-business]').forEach(b=>b.onclick=()=>openSavedRequest(b.dataset.openBusiness));root.querySelectorAll('[data-open-project]').forEach(b=>b.onclick=()=>{mobileDetail=false;projectFilter=b.dataset.openProject;projectKind='';projectTab='overview';selected=null;view='overview';search='';statusFilter='All';resetRequestDates();api.refresh({resetScroll:true});});root.querySelectorAll('[data-project-list-kind]').forEach(b=>b.onclick=()=>{mobileDetail=false;projectKind=b.dataset.projectListKind;selected=null;view='overview';api.refresh();$(`[data-project-list-kind=${projectKind}]`)?.focus({preventScroll:true});});if($('#project-search'))$('#project-search').oninput=e=>{projectSearch=e.target.value;const pos=e.target.selectionStart;api.refresh();$('#project-search').focus({preventScroll:true});$('#project-search').setSelectionRange(pos,pos);};root.querySelectorAll('[data-business-request]').forEach(b=>b.onclick=()=>{ledgerScroll=$('#business-page').scrollTop;mobileDetail=true;selected=b.dataset.businessRequest;view='overview';api.refresh({resetScroll:true});$('#business-page').scrollTop=0;$('.business-mobile-back')?.focus({preventScroll:true});});root.querySelectorAll('[data-business-view]').forEach(b=>b.onclick=()=>switchDetailView(b.dataset.businessView));root.querySelectorAll('[data-biz]').forEach(b=>b.onclick=async()=>{try{const a=b.dataset.biz;if(a==='request-list'){mobileDetail=false;api.refresh();$('#business-page').scrollTop=ledgerScroll;document.querySelector('[data-business-request="'+selected+'"]')?.focus({preventScroll:true});return;}if(a==='filters')return moreFilters();if(a==='customer-new')return customerDialog();if(a==='new-context')return scope==='projects'?projectRequestChoice(true):requestProject==='company'||requestKind==='corporation'?requestForm({kind:'corporation'}):openBusinessRequest();if(a==='new')return openBusinessRequest();if(a==='projects')return projectList();if(a==='project-home'){showProjects();return api.refresh({resetScroll:true});}if(a==='customer-access-settings')return customerAccessDialog(data().projects.find(p=>p.id===projectFilter));if(a==='customer-view-preview')return previewProjectCustomer(data().projects.find(p=>p.id===projectFilter));if(a==='project-invite')return projectInviteDialog(data().projects.find(p=>p.id===projectFilter));if(a==='share-contracts')return shareContractsDialog(selectedRequest());if(a==='project-settings')return projectDialog(data().projects.find(p=>p.id===projectFilter));if(a==='project-new')return projectDialog();await simpleAction(a,selectedRequest());}catch(e){api.notify(e.message);}});if($('#business-status'))$('#business-status').onchange=e=>{statusFilter=e.target.value;api.refresh();};if($('#business-period'))$('#business-period').onchange=e=>{if(e.target.value==='custom'){e.target.value=datePeriod;moreFilters('custom');return;}datePeriod=e.target.value;mobileDetail=false;selected=null;api.refresh();$('#business-period')?.focus({preventScroll:true});};for(const [id,key] of [['business-date-from','from'],['business-date-to','to']]){const field=$('#'+id);if(field)field.onchange=e=>{if(key==='from')dateFrom=e.target.value;else dateTo=e.target.value;mobileDetail=false;selected=null;api.refresh();$('#'+id)?.focus({preventScroll:true});};}if($('#business-search'))$('#business-search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;api.refresh();$('#business-search').focus({preventScroll:true});$('#business-search').setSelectionRange(pos,pos);};}
